(input) => {
    const parts = String(input ?? '').trim().split(/\s+/).filter(Boolean).map(Number);
    const n = parts[0] ?? 0;
    const m = parts[1] ?? 0;
    const rows = [];

    for (let i = 0; i < n; i++) {
      if (i % 2 === 0) {
        rows.push('#'.repeat(m));
      } else if (Math.floor(i / 2) % 2 === 0) {
        rows.push('.'.repeat(Math.max(0, m - 1)) + '#');
      } else {
        rows.push('#' + '.'.repeat(Math.max(0, m - 1)));
      }
    }

    return rows.join('\n');
  }

